package fastdisplay;

import fastcore.FastCore;

public class FastDesktop {

    static {
        FastCore.loadLibrary("fastdisplay");
    }

    public static class DesktopInfo {
        public final String id;
        public final String name;
        public final boolean isCurrent;

        public DesktopInfo(String id, String name, boolean isCurrent) {
            this.id = id;
            this.name = name;
            this.isCurrent = isCurrent;
        }
    }

    public interface DesktopListener {
        void onDesktopChanged(String newDesktopId);
        void onDesktopCreated(String desktopId);
        void onDesktopDeleted(String desktopId);
        void onWindowMovedToDesktop(long hwnd, String desktopId);
    }

    public native DesktopInfo[] enumerateDesktops();
    public native String getCurrentDesktopId();
    public native boolean switchDesktop(String desktopId);
    public native boolean moveWindowToDesktop(long hwnd, String desktopId);
    public native void setListener(DesktopListener l);
}

#include <windows.h>
#include <iostream>
#include <vector>

int main() {
    DISPLAY_DEVICEW dd = {};
    dd.cb = sizeof(dd);
    if (!EnumDisplayDevicesW(nullptr, 0, &dd, 0)) {
        std::cout << "EnumDisplayDevicesW failed\n";
        return 1;
    }

    std::wcout << L"Device: " << dd.DeviceName << L"\n";

    HDC hdc = CreateDCW(nullptr, dd.DeviceName, nullptr, nullptr);
    if (!hdc) {
        std::cout << "CreateDCW failed\n";
        return 1;
    }

    // Try without SetICMMode
    DWORD size = 0;
    if (GetICMProfileW(hdc, &size, nullptr) || GetLastError() == ERROR_INSUFFICIENT_BUFFER) {
        std::vector<wchar_t> path(size);
        if (GetICMProfileW(hdc, &size, path.data())) {
            std::wcout << L"Profile (without ICM_ON): " << path.data() << L"\n";
        } else {
            std::cout << "GetICMProfileW failed 1. Error: " << GetLastError() << "\n";
        }
    } else {
        std::cout << "GetICMProfileW size query failed. Error: " << GetLastError() << "\n";
    }

    int oldMode = SetICMMode(hdc, ICM_ON);
    std::cout << "SetICMMode returned: " << oldMode << "\n";

    size = 0;
    if (GetICMProfileW(hdc, &size, nullptr) || GetLastError() == ERROR_INSUFFICIENT_BUFFER) {
        std::vector<wchar_t> path(size);
        if (GetICMProfileW(hdc, &size, path.data())) {
            std::wcout << L"Profile (with ICM_ON): " << path.data() << L"\n";
        } else {
            std::cout << "GetICMProfileW failed 2. Error: " << GetLastError() << "\n";
        }
    } else {
        std::cout << "GetICMProfileW size query failed 2. Error: " << GetLastError() << "\n";
    }

    DeleteDC(hdc);
    return 0;
}

