// Utilities for GUID <-> String
static std::string GuidToString(const GUID& guid) {
    char buf[64];
    snprintf(buf, sizeof(buf), "%08X-%04X-%04X-%02X%02X-%02X%02X%02X%02X%02X%02X",
             guid.Data1, guid.Data2, guid.Data3,
             guid.Data4[0], guid.Data4[1],
             guid.Data4[2], guid.Data4[3], guid.Data4[4],
             guid.Data4[5], guid.Data4[6], guid.Data4[7]);
    return std::string(buf);
}

static GUID StringToGuid(const std::string& str) {
    GUID guid = {};
    sscanf_s(str.c_str(), "%08lx-%04hx-%04hx-%02hhx%02hhx-%02hhx%02hhx%02hhx%02hhx%02hhx%02hhx",
             &guid.Data1, &guid.Data2, &guid.Data3,
             &guid.Data4[0], &guid.Data4[1],
             &guid.Data4[2], &guid.Data4[3], &guid.Data4[4],
             &guid.Data4[5], &guid.Data4[6], &guid.Data4[7]);
    return guid;
}

static Fast_IVirtualDesktopManagerInternal* GetInternalManager() {
    Fast_IVirtualDesktopManagerInternal* pManager = nullptr;
    CoCreateInstance(CLSID_VirtualDesktopManagerInternal, nullptr, CLSCTX_ALL, __uuidof(Fast_IVirtualDesktopManagerInternal), (void**)&pManager);
    return pManager;
}

