package fastdisplay;

import java.nio.charset.StandardCharsets;
import java.util.Arrays;
import java.util.HashMap;
import java.util.Map;

public final class FastDisplayUtils {

    private FastDisplayUtils() {}

    // ------------------------------------------------------------
    // 1) EDID PARSING
    // ------------------------------------------------------------

    public static String parseManufacturer(byte[] edid) {
        if (edid == null || edid.length < 10) return "Unknown";
        int raw = ((edid[8] & 0xFF) << 8) | (edid[9] & 0xFF);
        char c1 = (char) ('A' + ((raw >> 10) & 0x1F) - 1);
        char c2 = (char) ('A' + ((raw >> 5) & 0x1F) - 1);
        char c3 = (char) ('A' + (raw & 0x1F) - 1);
        return "" + c1 + c2 + c3;
    }

    public static String parseModelName(byte[] edid) {
        if (edid == null || edid.length < 126) return "Unknown";
        for (int i = 54; i < 126; i += 18) {
            if (edid[i] == 0x00 && edid[i+1] == 0x00 && edid[i+2] == 0x00 && edid[i+3] == (byte)0xFC) {
                byte[] block = Arrays.copyOfRange(edid, i + 5, i + 18);
                String s = new String(block, StandardCharsets.US_ASCII).trim();
                return s.replace("\n", "").replace("\r", "");
            }
        }
        return "Unknown";
    }

    public static String parseSerialNumber(byte[] edid) {
        if (edid == null || edid.length < 126) return "Unknown";
        for (int i = 54; i < 126; i += 18) {
            if (edid[i] == 0x00 && edid[i+1] == 0x00 && edid[i+2] == 0x00 && edid[i+3] == (byte)0xFF) {
                byte[] block = Arrays.copyOfRange(edid, i + 5, i + 18);
                return new String(block, StandardCharsets.US_ASCII).trim();
            }
        }
        return "Unknown";
    }

    public static double parseSizeInInches(byte[] edid) {
        if (edid == null || edid.length < 23) return 0;
        int w = edid[21] & 0xFF;
        int h = edid[22] & 0xFF;
        if (w == 0 || h == 0) return 0;
        double diagCm = Math.sqrt(w * w + h * h);
        return diagCm / 2.54;
    }

    public static int parseNativeWidth(byte[] edid) {
        if (edid == null || edid.length < 59) return 0;
        return ((edid[56] & 0xF0) << 4) | (edid[58] & 0xFF);
    }

    public static int parseNativeHeight(byte[] edid) {
        if (edid == null || edid.length < 60) return 0;
        return ((edid[57] & 0xF0) << 4) | (edid[59] & 0xFF);
    }

    // ------------------------------------------------------------
    // 2) CTA-861 HDR CAPABILITIES
    // ------------------------------------------------------------

    public static Map<String, Boolean> parseHdrCapabilities(byte[] edid) {
        Map<String, Boolean> caps = new HashMap<>();

        // CTA-861 Extension Block at 0x80
        if (edid == null || edid.length < 256) {
            caps.put("HDR", false);
            return caps;
        }

        byte[] ext = Arrays.copyOfRange(edid, 128, 256);
        if (ext[0] != 0x02) {
            caps.put("HDR", false);
            return caps;
        }

        int dtdStart = ext[2] & 0xFF;
        int pos = 4;

        while (pos < dtdStart) {
            int tag = (ext[pos] & 0xE0) >> 5;
            int len = ext[pos] & 0x1F;
            int blockStart = pos + 1;

            // Extended tag
            if (tag == 0x07) {
                int extTag = ext[blockStart] & 0xFF;

                // HDR Static Metadata Block
                if (extTag == 0x06) {
                    int eotf = ext[blockStart + 1] & 0xFF;
                    caps.put("HDR", true);
                    caps.put("PQ", (eotf & 0b00000100) != 0);
                    caps.put("HLG", (eotf & 0b00001000) != 0);
                }
            }

            pos += 1 + len;
        }

        return caps;
    }

    // ------------------------------------------------------------
    // 3) ICC PROFILE HEADER PARSING
    // ------------------------------------------------------------

    public static Map<String, Object> parseIccHeader(byte[] icc) {
        Map<String, Object> info = new HashMap<>();
        if (icc == null || icc.length < 128) return info;

        String signature = new String(Arrays.copyOfRange(icc, 36, 40), StandardCharsets.US_ASCII);
        String deviceClass = new String(Arrays.copyOfRange(icc, 12, 16), StandardCharsets.US_ASCII);
        String colorSpace = new String(Arrays.copyOfRange(icc, 16, 20), StandardCharsets.US_ASCII);

        info.put("signature", signature);
        info.put("deviceClass", deviceClass);
        info.put("colorSpace", colorSpace);

        return info;
    }

    // ------------------------------------------------------------
    // 4) JSON EXPORTER
    // ------------------------------------------------------------

    public static String toJson(Map<String, ?> map) {
        StringBuilder sb = new StringBuilder("{");
        boolean first = true;
        for (var e : map.entrySet()) {
            if (!first) sb.append(",");
            first = false;
            sb.append("\"").append(e.getKey()).append("\":");

            Object v = e.getValue();
            if (v instanceof Number || v instanceof Boolean) {
                sb.append(v.toString());
            } else {
                sb.append("\"").append(v).append("\"");
            }
        }
        sb.append("}");
        return sb.toString();
    }

    // ------------------------------------------------------------
    // 5) DEBUG HELPERS
    // ------------------------------------------------------------

    public static String hexDump(byte[] data) {
        if (data == null) return "null";
        StringBuilder sb = new StringBuilder();
        for (int i = 0; i < data.length; i++) {
            if (i % 16 == 0) sb.append(String.format("%n%04X: ", i));
            sb.append(String.format("%02X ", data[i]));
        }
        return sb.toString().trim();
    }
}

package fastdisplay;

/**
 * Demo - Display Monitoring Example using FastDisplay v1.0.0 API.
 *
 * <p>This demo showcases the display monitoring capabilities of FastDisplay:
 * <ul>
 *   <li>Real-time resolution change detection</li>
 *   <li>DPI scaling change events</li>
 *   <li>Display orientation monitoring</li>
 *   <li>Refresh rate information</li>
 * </ul>
 *
 * <p><b>How it works:</b> FastDisplay creates a hidden message-only window and
 * background thread that listens for Windows system events:
 * <ul>
 *   <li>WM_DISPLAYCHANGE - Resolution/DPI changes</li>
 *   <li>WM_DPICHANGED - DPI scaling changes</li>
 * </ul>
 *
 * <p><b>Usage:</b> Run and try changing display settings.</p>
 *
 * @see FastDisplay#startMonitoring()
 * @see FastDisplay.DisplayListener
 * @version 1.0.0
 */
public class Demo {
    public static void main(String[] args) {
        clearConsole();

        System.out.println("FastDisplay v0.2.0");
        System.out.println("────────────────────────────────────────────────────────");
        System.out.println();

        FastDisplay display = new FastDisplay();

        FastDisplay.MonitorInfo[] monitors = display.enumerateMonitors();
        if (monitors != null && monitors.length > 0) {
            for (FastDisplay.MonitorInfo m : monitors) {
                System.out.println(m.toString());

                // Feature 4: FastDisplayUtils test
                byte[] edid = display.getEdidForMonitor(m.index);
                if (edid != null) {
                    System.out.println("  Manufacturer : " + FastDisplayUtils.parseManufacturer(edid));
                    System.out.println("  Model Name   : " + FastDisplayUtils.parseModelName(edid));
                    System.out.println("  Serial Number: " + FastDisplayUtils.parseSerialNumber(edid));
                    System.out.println("  Size         : " + FastDisplayUtils.parseSizeInInches(edid) + " inches");
                    System.out.println("  HDR Caps     : " + FastDisplayUtils.parseHdrCapabilities(edid));
                } else {
                    System.out.println("  EDID: not available");
                }

                String profile = display.getColorProfileForMonitor(m.index);
                System.out.println("  ICC Profile  : " + (profile != null ? profile : "None"));
                System.out.println("  DXGI HDR     : " + display.isHdrEnabled(m.index));
                System.out.println();
            }
        }

        System.out.println("VIRTUAL DESKTOPS");
        System.out.println("────────────────────────────────────────────────────────");
        try {
            FastDesktop desktop = new FastDesktop();
            String currentId = desktop.getCurrentDesktopId();
            System.out.println("Current Desktop ID: " + currentId);
            FastDesktop.DesktopInfo[] desktops = desktop.enumerateDesktops();
            if (desktops != null) {
                System.out.println("Total Desktops: " + desktops.length);
                for (FastDesktop.DesktopInfo d : desktops) {
                    System.out.println("  - " + d.name + " (" + d.id + ") " + (d.isCurrent ? "[ACTIVE]" : ""));
                }
            }
        } catch (Throwable t) {
            System.out.println("Virtual Desktops not supported or failed: " + t.getMessage());
        }
        System.out.println();

        System.out.println("EVENT LOG");
        System.out.println("────────────────────────────────────────────────────────");

        display.setListener(new FastDisplay.DisplayListener() {
            @Override
            public void onInitialState(int width, int height, int dpi, int refreshRate,
                                       FastDisplay.Orientation orientation) {
                // Initial state already shown by enumerateMonitors() above
            }

            @Override
            public void onResolutionChanged(int monitorIndex, int width, int height, int dpi, int refreshRate) {
                printDisplayInfo(monitorIndex, width, height, dpi, refreshRate, null, "[EVENT]", "[RESOLUTION]");
            }

            @Override
            public void onDPIChanged(int monitorIndex, int dpi, int scalePercent) {
                printDisplayInfo(monitorIndex, 0, 0, dpi, 0, null, "[EVENT]", "[DPI]");
            }

            @Override
            public void onOrientationChanged(int monitorIndex, FastDisplay.Orientation orientation) {
                printDisplayInfo(monitorIndex, 0, 0, 0, 0, orientation, "[EVENT]", "[ORIENTATION]");
            }

            @Override
            public void onColorProfileChanged(int monitorIndex) {
                System.out.printf("%-21s monitor=%d -> ICC profile updated%n", "[EVENT] [COLORPROFILE]", monitorIndex);
            }
        });

        display.startMonitoring();

        // Keep alive
        try {
            Thread.sleep(Long.MAX_VALUE);
        } catch (InterruptedException e) {
            display.stopMonitoring();
        }
    }

    private static void printDisplayInfo(int monitor, int width, int height, int dpi, int refreshRate, FastDisplay.Orientation orientation, String prefix, String eventType) {
        int scalePercent = (dpi * 100) / 96;
        String orientationName = orientation != null ? orientation.name() : "-";
        String monitorStr = monitor >= 0 ? String.valueOf(monitor) : "-";

        String prefixFormatted = prefix;
        if (!eventType.isEmpty()) {
            prefixFormatted += " " + eventType;
        }

        // Format based on event type
        if ("[DPI]".equals(eventType)) {
            System.out.printf("%-21s monitor=%s → dpi=%-3d (%-3d%%)%n",
                prefixFormatted, monitorStr, dpi, scalePercent);
        } else if ("[ORIENTATION]".equals(eventType)) {
            System.out.printf("%-21s monitor=%s → %s%n",
                prefixFormatted, monitorStr, orientationName);
        } else if ("[RESOLUTION]".equals(eventType)) {
            System.out.printf("%-21s monitor=%s → %d×%d @ %d Hz, dpi=%-3d (%-3d%%)%n",
                prefixFormatted, monitorStr, width, height, refreshRate, dpi, scalePercent);
        } else {
            // FULL or default (PRESENT/CURRENT)
            System.out.printf("%-21s monitor=%s, res=%dx%d, dpi=%-3d, scale=%-3d%%, hz=%-3d, orientation=%s%n",
                prefixFormatted, monitorStr, width, height, dpi, scalePercent, refreshRate, orientationName);
        }
    }

    private static void clearConsole() {
        try {
            if (System.getProperty("os.name").contains("Windows")) {
                new ProcessBuilder("cmd", "/c", "cls").inheritIO().start().waitFor();
            } else {
                System.out.print("\033[H\033[2J");
                System.out.flush();
            }
        } catch (Exception e) {
            // Ignore if clear fails
        }
    }
}

package fastdisplay;

import fastcore.FastCore;

/**
 * FastDisplay – Native Windows Display Monitoring API for Java.
 *
 * <p>Provides real-time monitoring of display changes (resolution, DPI,
 * refresh rate, orientation) via JNI.</p>
 *
 * <p>All callbacks occur on the monitoring thread. If UI-thread dispatching
 * is required (Swing/JavaFX), the application must forward events manually.</p>
 *
 * <p><b>Platform:</b> Windows 10/11 (Win32 API)</p>
 *
 * <p><b>Usage Example:</b></p>
 * <pre>{@code
 * FastDisplay display = new FastDisplay();
 * display.setListener(new FastDisplay.DisplayListener() {
 *     @Override
 *     public void onInitialState(int width, int height, int dpi, int refreshRate, Orientation orientation) {
 *         System.out.println("Initial: " + width + "x" + height + " @ " + dpi + " DPI");
 *     }
 *     
 *     @Override
 *     public void onResolutionChanged(int monitorIndex, int width, int height, int dpi, int refreshRate) {
 *         System.out.println("Resolution changed: " + width + "x" + height);
 *     }
 *     
 *     @Override
 *     public void onDPIChanged(int monitorIndex, int dpi, int scalePercent) {
 *         System.out.println("DPI changed: " + dpi + " (" + scalePercent + "%)");
 *     }
 *     
 *     @Override
 *     public void onOrientationChanged(int monitorIndex, Orientation orientation) {
 *         System.out.println("Orientation changed: " + orientation);
 *     }
 * });
 * 
 * if (display.startMonitoring()) {
 *     // Monitor until stopped
 *     display.stopMonitoring();
 * }
 * }</pre>
 *
 * @author Andre Stubbe
 * @version 1.0.0
 */
public class FastDisplay {
    /** Default constructor. Initializes the FastDisplay instance. */
    public FastDisplay() {}

    static {
        FastCore.loadLibrary("fastdisplay");
    }

    /** Display orientation values returned by the native API.
     * 
     * <p>These values correspond to the Windows DM_DISPLAYORIENTATION constants:</p>
     * <ul>
     * <li>LANDSCAPE - 0° rotation (default)</li>
     * <li>PORTRAIT - 90° clockwise rotation</li>
     * <li>LANDSCAPE_FLIPPED - 180° rotation</li>
     * <li>PORTRAIT_FLIPPED - 270° clockwise rotation</li>
     * </ul>
     */
    public enum Orientation {
        /** Standard landscape orientation (0°). */
        LANDSCAPE,
        /** Portrait orientation (90° clockwise rotation). */
        PORTRAIT,
        /** Landscape flipped (180° rotation). */
        LANDSCAPE_FLIPPED,
        /** Portrait flipped (270° clockwise rotation). */
        PORTRAIT_FLIPPED
    }

    /**
     * Immutable monitor information returned by {@code enumerateMonitors()}.
     */
    public static final class MonitorInfo {
        /** Monitor index (0-based). */
        public final int index;
        /** Display width in pixels. */
        public final int width;
        /** Display height in pixels. */
        public final int height;
        /** Dots per inch. */
        public final int dpi;
        /** Display orientation. */
        public final Orientation orientation;
        /** Refresh rate in Hz. */
        public final int refreshRate;

        // Extended Information
        /** True if HDR is enabled for this monitor. */
        public final boolean hdrEnabled;
        /** Color profile path or name (e.g., ICC/ICM). */
        public final String colorProfile;
        /** Raw EDID data. */
        public final byte[] edid;

        /**
         * Constructs a MonitorInfo object with extended features.
         * @param index monitor index
         * @param width display width
         * @param height display height
         * @param dpi dots per inch
         * @param orientation display orientation
         * @param refreshRate refresh rate in Hz
         * @param hdrEnabled true if HDR is enabled
         * @param colorProfile path to color profile
         * @param edid raw EDID data
         */
        public MonitorInfo(int index, int width, int height, int dpi,
                           Orientation orientation, int refreshRate,
                           boolean hdrEnabled, String colorProfile, byte[] edid) {
            this.index = index;
            this.width = width;
            this.height = height;
            this.dpi = dpi;
            this.orientation = orientation;
            this.refreshRate = refreshRate;
            this.hdrEnabled = hdrEnabled;
            this.colorProfile = colorProfile;
            this.edid = edid;
        }

        /**
         * Backwards-compatible constructor for old native signatures.
         */
        public MonitorInfo(int index, int width, int height, int dpi,
                           Orientation orientation, int refreshRate) {
            this(index, width, height, dpi, orientation, refreshRate, false, null, null);
        }

        @Override
        public String toString() {
            StringBuilder sb = new StringBuilder();
            int scalePercent = (dpi * 100) / 96;
            sb.append("MONITOR ").append(index).append("\n");
            sb.append("────────────────────────────────────────────────────────\n");
            sb.append(String.format("Resolution : %d × %d @ %d Hz\n", width, height, refreshRate));
            sb.append(String.format("DPI        : %d (%d%%)\n", dpi, scalePercent));
            sb.append("Orientation: ").append(orientation).append("\n");
            return sb.toString();
        }
    }

    /**
     * Listener interface for receiving display change events.
     * 
     * <p>All listener methods are called on the monitoring thread. If you need to update
     * UI components (Swing/JavaFX), you must dispatch the event to the UI thread manually.</p>
     * 
     * <p>Event filtering is applied to prevent duplicate events - the same value will not
     * be reported twice in succession.</p>
     */
    public interface DisplayListener {
        /** Called once with initial display state when monitoring starts.
         * 
         * @param width display width in pixels
         * @param height display height in pixels
         * @param dpi dots per inch (96 = 100% scale)
         * @param refreshRate refresh rate in Hz
         * @param orientation current display orientation
         */
        void onInitialState(int width, int height, int dpi, int refreshRate, Orientation orientation);

        /** Called when display resolution changes.
         * 
         * <p>This event fires when the actual pixel resolution or refresh rate changes.
         * DPI-only changes are reported via {@link #onDPIChanged}.</p>
         * 
         * @param monitorIndex monitor index (0-based)
         * @param width new display width in pixels
         * @param height new display height in pixels
         * @param dpi current DPI value
         * @param refreshRate new refresh rate in Hz
         */
        void onResolutionChanged(int monitorIndex, int width, int height, int dpi, int refreshRate);

        /** Called when DPI scaling changes.
         * 
         * <p>This event fires when the user changes the display scale in Windows settings
         * (e.g., from 100% to 150%). The DPI value changes, but the pixel resolution
         * remains the same.</p>
         * 
         * @param monitorIndex monitor index (0-based)
         * @param dpi new DPI value (96 = 100% scale)
         * @param scalePercent scale percentage (100, 125, 150, 175, 200, etc.)
         */
        void onDPIChanged(int monitorIndex, int dpi, int scalePercent);

        /** Called when display orientation changes.
         * 
         * <p>This event fires when the display is rotated (e.g., on a tablet or
         * when using a monitor with rotation support).</p>
         * 
         * @param monitorIndex monitor index (0-based)
         * @param orientation new display orientation
         */
        void onOrientationChanged(int monitorIndex, Orientation orientation);

        /** Called when display color profile changes. */
        void onColorProfileChanged(int monitorIndex);
    }

    // ============================
    // Instance Fields
    // ============================

    /** The registered listener for display events. */
    private DisplayListener listener;

    // ============================
    // Event Filtering
    // ============================

    /** Tracking variables to prevent duplicate events. */
    private int lastReportedWidth = 0;
    private int lastReportedHeight = 0;
    private int lastReportedDpi = 0;
    private int lastReportedRefreshRate = 0;
    private Orientation lastReportedOrientation = null;

    // ============================
    // Public API
    // ============================

    /** Assign a listener for display events.
     * 
     * @param listener the listener to set, or null to remove the current listener
     */
    public void setListener(DisplayListener listener) {
        this.listener = listener;
    }

    // ============================
    // Native Callback Handlers
    // ============================

    /** Called from native code with initial display state. */
    private void notifyInitialState(int w, int h, int dpi, int orientationOrdinal, int refresh) {
        if (listener != null) {
            lastReportedWidth = w;
            lastReportedHeight = h;
            lastReportedDpi = dpi;
            lastReportedRefreshRate = refresh;
            lastReportedOrientation = Orientation.values()[orientationOrdinal];
            listener.onInitialState(w, h, dpi, refresh, lastReportedOrientation);
        }
    }

    /** Called from native code when resolution changes. */
    private void notifyResolutionChanged(int monitorIndex, int w, int h, int dpi, int refresh) {
        if (listener != null) {
            if (w != lastReportedWidth || h != lastReportedHeight || refresh != lastReportedRefreshRate) {
                lastReportedWidth = w;
                lastReportedHeight = h;
                lastReportedRefreshRate = refresh;
                listener.onResolutionChanged(monitorIndex, w, h, dpi, refresh);
            }
        }
    }

    /** Called from native code when orientation changes. */
    private void notifyOrientationChanged(int monitorIndex, int orientationOrdinal) {
        if (listener != null) {
            Orientation newOrientation = Orientation.values()[orientationOrdinal];
            if (newOrientation != lastReportedOrientation) {
                lastReportedOrientation = newOrientation;
                listener.onOrientationChanged(monitorIndex, newOrientation);
            }
        }
    }

    /** Called from native code with debug messages. */
    private void notifyDebug(String message) {
        // No-op: override or log as needed
    }

    /** Called from native code when DPI changes. */
    private void notifyDPIChanged(int monitorIndex, int dpi, int scalePercent) {
        if (listener != null) {
            if (dpi != lastReportedDpi) {
                lastReportedDpi = dpi;
                listener.onDPIChanged(monitorIndex, dpi, scalePercent);
            }
        }
    }

    /** Called from native code when Color Profile changes. */
    private void notifyColorProfileChanged(int monitorIndex) {
        if (listener != null) {
            listener.onColorProfileChanged(monitorIndex);
        }
    }

    // ============================
    // Native Method Declarations
    // ============================

    /** Start monitoring display changes.
     * 
     * <p>Creates a background thread that listens for Windows display change events.
     * The listener's {@link DisplayListener#onInitialState} method will be called
     * immediately with the current display state.</p>
     * 
     * @return true if monitoring started successfully, false if already monitoring or failed
     */
    public native boolean startMonitoring();

    /** Stop monitoring display changes.
     * 
     * <p>Stops the background monitoring thread and releases native resources.
     * This method is idempotent - calling it multiple times is safe.</p>
     */
    public native void stopMonitoring();

    /** Enumerate all connected monitors.
     * 
     * <p>Returns information about all currently connected displays including
     * resolution, DPI, orientation, and refresh rate.</p>
     * 
     * @return array of MonitorInfo objects, or null if enumeration fails
     */
    public native MonitorInfo[] enumerateMonitors();

    /** Get current display resolution.
     * 
     * @return int array with [width, height], or null if failed
     */
    public native int[] getResolution();

    /** Get current display scale percentage.
     * 
     * @return scale percentage (e.g., 100, 125, 150), or 0 if failed
     */
    public native int getScale();

    /** Get current display orientation.
     * 
     * @return current orientation, or null if failed
     */
    public native Orientation getOrientation();

    // ============================
    // Extended Monitor Features (v1.1+)
    // ============================

    /** Check if HDR is enabled for the specified monitor.
     * 
     * @param monitorIndex monitor index
     * @return true if HDR is enabled, false otherwise
     */
    public native boolean isHdrEnabled(int monitorIndex);

    /** Get the active color profile (ICC/ICM) for the specified monitor.
     * 
     * @param monitorIndex monitor index
     * @return color profile path/name, or null if not available
     */
    public native String getColorProfileForMonitor(int monitorIndex);

    /** Get the raw EDID data for the specified monitor.
     * 
     * @param monitorIndex monitor index
     * @return byte array containing EDID data, or null if not available
     */
    public native byte[] getEdidForMonitor(int monitorIndex);

    /** Set the brightness for the specified monitor.
     * 
     * <p>Note: This is heavily dependent on the physical monitor and graphics driver.</p>
     * 
     * @param monitorIndex monitor index
     * @param percent brightness percentage (0-100)
     * @return true if successfully set, false otherwise
     */
    public native boolean setBrightness(int monitorIndex, int percent);
}

/**
 * @file FastDisplay.cpp
 * @brief Native Windows display monitoring implementation for Java via JNI
 * 
 * This file implements the FastDisplay native library that provides real-time
 * monitoring of Windows display changes (resolution, DPI, refresh rate, orientation).
 * 
 * Architecture:
 * - Background thread creates a hidden window to receive Windows messages
 * - WM_DISPLAYCHANGE: Resolution and refresh rate changes
 * - WM_DPICHANGED: DPI scaling changes (when supported)
 * - Polling timers: Backup mechanism for DPI and refresh rate detection
 * - JNI callbacks: Events are forwarded to Java listener
 * 
 * Thread Safety:
 * - Monitor data protected by monitorMutex
 * - Global handles are atomic
 * - JNI thread attachment/detachment handled per callback
 * 
 * @author Andre Stubbe
 * @version 1.0.0
 */

#include <windows.h>
#include <shellscalingapi.h>
#include <dxgi1_6.h>
#include <icm.h>
#include <setupapi.h>
#include <devguid.h>
#include <cfgmgr32.h>
#include <jni.h>
#include <mutex>
#include <atomic>
#include <vector>
#include <highlevelmonitorconfigurationapi.h>

#pragma comment(lib, "user32.lib")
#pragma comment(lib, "gdi32.lib")
#pragma comment(lib, "shcore.lib")
#pragma comment(lib, "advapi32.lib")
#pragma comment(lib, "dxgi.lib")
#pragma comment(lib, "setupapi.lib")
#pragma comment(lib, "cfgmgr32.lib")
#pragma comment(lib, "Dxva2.lib")

#define MAX_DEVICE_ID_LEN 200

// ============================================================================
// DATA STRUCTURES
// ============================================================================

/**
 * @brief Monitor information structure
 * 
 * Stores all relevant display information for a single monitor.
 * Protected by monitorMutex for thread-safe access.
 */
struct MonitorInfo {
    HMONITOR handle;              ///< Windows monitor handle
    int index;                    ///< Monitor index (0-based)
    int width;                    ///< Display width in pixels
    int height;                   ///< Display height in pixels
    int dpi;                      ///< Dots per inch (96 = 100% scale)
    int orientation;              ///< Orientation (0=landscape, 1=portrait, etc.)
    int refreshRate;              ///< Refresh rate in Hz
    RECT rect;                    ///< Monitor screen rectangle
};

// ============================================================================
// GLOBAL STATE
// ============================================================================

/** Mutex protecting monitor data access */
static std::mutex monitorMutex;

/** Number of currently detected monitors */
static int monitorCount = 0;

/** Array of monitor information (max 16 monitors) */
static MonitorInfo monitors[16];

/** DPI polling timer handle */
static UINT_PTR g_dpiTimer = 0;

/** Flag indicating if DPI monitoring is active */
static std::atomic<bool> g_dpiMonitoring(false);

// ============================================================================
// FORWARD DECLARATIONS
// ============================================================================

static VOID CALLBACK DPICallback(HWND hwnd, UINT uMsg, UINT_PTR idEvent, DWORD dwTime);
static int findMonitorIndex(HMONITOR hMonitor);

// ============================================================================
// HELPER FUNCTIONS
// ============================================================================


/**
 * @brief Callback for enumerating all monitors
 * 
 * Called by EnumDisplayMonitors for each monitor in the system.
 * Collects display information including resolution, DPI, refresh rate, and orientation.
 * 
 * @param hMonitor Monitor handle
 * @param hdcMonitor Device context (unused)
 * @param lprcMonitor Monitor rectangle
 * @param dwData User data (unused)
 * @return TRUE to continue enumeration
 */
static BOOL CALLBACK EnumMonitorsCallback(HMONITOR hMonitor, HDC hdcMonitor, LPRECT lprcMonitor, LPARAM dwData) {
    MONITORINFOEXW mi = {};
    mi.cbSize = sizeof(mi);
    GetMonitorInfoW(hMonitor, &mi);

    int width = lprcMonitor->right - lprcMonitor->left;
    int height = lprcMonitor->bottom - lprcMonitor->top;

    // Get DPI for this monitor
    UINT dpiX = 96, dpiY = 96;
    GetDpiForMonitor(hMonitor, MDT_EFFECTIVE_DPI, &dpiX, &dpiY);

    // Get refresh rate and orientation
    DEVMODEW dm = {};
    dm.dmSize = sizeof(dm);
    int refreshRate = 60;
    int orientation = 0;
    if (EnumDisplaySettingsW(mi.szDevice, ENUM_CURRENT_SETTINGS, &dm)) {
        if (dm.dmFields & DM_PELSWIDTH) width = dm.dmPelsWidth;
        if (dm.dmFields & DM_PELSHEIGHT) height = dm.dmPelsHeight;
        if (dm.dmFields & DM_DISPLAYFREQUENCY) refreshRate = dm.dmDisplayFrequency;
        if (dm.dmFields & DM_DISPLAYORIENTATION) {
            switch (dm.dmDisplayOrientation) {
                case DMDO_DEFAULT: orientation = 0; break;
                case DMDO_90: orientation = 1; break;
                case DMDO_180: orientation = 2; break;
                case DMDO_270: orientation = 3; break;
            }
        }
    }


    if (monitorCount < 16) {
        monitors[monitorCount].handle = hMonitor;
        monitors[monitorCount].index = monitorCount;
        monitors[monitorCount].width = width;
        monitors[monitorCount].height = height;
        monitors[monitorCount].dpi = (int)dpiX;
        monitors[monitorCount].orientation = orientation;
        monitors[monitorCount].refreshRate = refreshRate;
        monitors[monitorCount].rect = *lprcMonitor;
        monitorCount++;
    }

    return TRUE;
}

// ============================================================================
// JNI GLOBAL STATE
// ============================================================================

/** Java VM instance (set during initialization) */
static JavaVM* g_jvm = nullptr;

/** Java FastDisplay object reference (global) */
static jobject g_displayObj = nullptr;

/** JNI method IDs for callbacks */
static jmethodID g_notifyMethodId = nullptr;
static jmethodID g_notifyDPIMethodId = nullptr;
static jmethodID g_notifyInitialStateMethodId = nullptr;
static jmethodID g_notifyOrientationChangedMethodId = nullptr;
static jmethodID g_notifyDebugMethodId = nullptr;

/** Hidden window handle for receiving Windows messages (atomic for thread safety) */
static std::atomic<HWND> g_hwnd = nullptr;

/** Monitor thread ID */
static DWORD g_threadId = 0;
static int lastWidth = 0;
static int lastHeight = 0;
static int lastDpi = 0;
static int lastOrientation = 0;

// Helper function to log debug messages to Java
static void logDebug(const char* message) {
    if (!g_jvm || !g_displayObj || !g_notifyDebugMethodId) return;

    JNIEnv* env;
    jint attachResult = g_jvm->GetEnv((void**)&env, JNI_VERSION_1_6);
    bool didAttach = false;

    if (attachResult == JNI_EDETACHED) {
        if (g_jvm->AttachCurrentThread((void**)&env, nullptr) == 0) {
            didAttach = true;
        } else {
            return;
        }
    } else if (attachResult != JNI_OK) {
        return;
    }

    jstring msg = env->NewStringUTF(message);
    env->CallVoidMethod(g_displayObj, g_notifyDebugMethodId, msg);
    env->DeleteLocalRef(msg);

    if (didAttach) {
        g_jvm->DetachCurrentThread();
    }
}

// ============================================================================
// JNI CALLBACK FUNCTIONS
// ============================================================================

/**
 * @brief DPI polling timer callback
 * 
 * Called every 500ms to check for DPI changes.
 * This is a backup mechanism for when WM_DPICHANGED doesn't fire.
 * Re-enumerates monitors and fires DPI events if DPI changes.
 * 
 * @param hwnd Window handle (unused)
 * @param uMsg Message ID (unused)
 * @param idEvent Timer ID (unused)
 * @param dwTime System time (unused)
 */
static VOID CALLBACK DPICallback(HWND hwnd, UINT uMsg, UINT_PTR idEvent, DWORD dwTime) {
    if (!g_jvm || !g_displayObj) return;

    JNIEnv* env;
    jint attachResult = g_jvm->GetEnv((void**)&env, JNI_VERSION_1_6);
    bool didAttach = false;

    if (attachResult == JNI_EDETACHED) {
        if (g_jvm->AttachCurrentThread((void**)&env, nullptr) == 0) {
            didAttach = true;
        } else {
            return;
        }
    } else if (attachResult != JNI_OK) {
        return;
    }

    // Save old DPI values before re-enumeration
    int oldDpiValues[16];
    {
        std::lock_guard<std::mutex> lock(monitorMutex);
        for (int i = 0; i < monitorCount; i++) {
            oldDpiValues[i] = monitors[i].dpi;
        }
    }

    // Re-enumerate monitors to get current state
    {
        std::lock_guard<std::mutex> lock(monitorMutex);
        monitorCount = 0;
        EnumDisplayMonitors(nullptr, nullptr, EnumMonitorsCallback, 0);
    }

    // Check each monitor for DPI changes
    std::lock_guard<std::mutex> lock(monitorMutex);
    for (int i = 0; i < monitorCount; i++) {
        UINT dpiX = 96, dpiY = 96;
        if (SUCCEEDED(GetDpiForMonitor(monitors[i].handle, MDT_EFFECTIVE_DPI, &dpiX, &dpiY))) {
            int newDpi = (int)dpiX;
            if (newDpi != oldDpiValues[i]) {
                // DPI changed - notify Java with DPI event
                int scalePercent = (newDpi * 100) / 96;
                if (g_notifyDPIMethodId) {
                    env->CallVoidMethod(g_displayObj, g_notifyDPIMethodId, i, newDpi, scalePercent);
                }
            }
        }
    }

    if (didAttach) {
        g_jvm->DetachCurrentThread();
    }
}


/**
 * @brief Find monitor index by HMONITOR handle
 * 
 * Searches the monitors array for a matching HMONITOR handle.
 * 
 * @param hMonitor Monitor handle to find
 * @return Monitor index, or -1 if not found
 */
static int findMonitorIndex(HMONITOR hMonitor) {
    if (hMonitor == nullptr) return -1;

    std::lock_guard<std::mutex> lock(monitorMutex);
    for (int i = 0; i < monitorCount; i++) {
        if (monitors[i].handle == hMonitor) {
            return i;
        }
    }

    return -1;
}

/**
 * @brief Send initial display state to Java
 * 
 * Called when monitoring starts to provide the current display configuration.
 * Sends resolution, DPI, refresh rate, and orientation to the Java listener.
 */
static void sendInitialState() {
    if (g_jvm == nullptr || g_displayObj == nullptr) return;

    JNIEnv* env;
    jint attachResult = g_jvm->GetEnv((void**)&env, JNI_VERSION_1_6);
    bool didAttach = false;

    if (attachResult == JNI_EDETACHED) {
        if (g_jvm->AttachCurrentThread((void**)&env, nullptr) != 0) {
            return;
        }
        didAttach = true;
    } else if (attachResult != JNI_OK) {
        return;
    }

    // Get current display settings
    int width = 0, height = 0;
    DEVMODE dm = {};
    dm.dmSize = sizeof(dm);
    int refreshRate = 60;
    int orientation = 0;
    int dpi = 96;

    if (EnumDisplaySettings(NULL, ENUM_CURRENT_SETTINGS, &dm)) {
        width = dm.dmPelsWidth;
        height = dm.dmPelsHeight;
        if (dm.dmFields & DM_DISPLAYFREQUENCY) refreshRate = dm.dmDisplayFrequency;
        if (dm.dmFields & DM_DISPLAYORIENTATION) {
            switch (dm.dmDisplayOrientation) {
                case DMDO_DEFAULT: orientation = 0; break;
                case DMDO_90: orientation = 1; break;
                case DMDO_180: orientation = 2; break;
                case DMDO_270: orientation = 3; break;
            }
        }
    } else {
        // Fallback to GetSystemMetrics
        width = GetSystemMetrics(SM_CXSCREEN);
        height = GetSystemMetrics(SM_CYSCREEN);
    }

    // Get DPI
    HMONITOR hMonitor = MonitorFromWindow(GetDesktopWindow(), MONITOR_DEFAULTTOPRIMARY);
    if (hMonitor) {
        UINT dpiX = 96, dpiY = 96;
        if (SUCCEEDED(GetDpiForMonitor(hMonitor, MDT_EFFECTIVE_DPI, &dpiX, &dpiY))) {
            dpi = (int)dpiX;
        }
    }

    env->CallVoidMethod(g_displayObj, g_notifyInitialStateMethodId,
        width, height, dpi, orientation, refreshRate);

    // Initialize tracking variables
    lastWidth = width;
    lastHeight = height;
    lastDpi = dpi;
    lastOrientation = orientation;

    if (didAttach) {
        g_jvm->DetachCurrentThread();
    }
}

/**
 * @brief Window procedure for the hidden monitoring window
 * 
 * Processes Windows messages related to display changes:
 * - WM_DISPLAYCHANGE: Resolution and refresh rate changes
 * - WM_DPICHANGED: DPI scaling changes
 * - WM_SETTINGCHANGE: System settings changes (color profiles)
 * 
 * @param hwnd Window handle
 * @param uMsg Message ID
 * @param wParam Message-specific parameter
 * @param lParam Message-specific parameter
 * @return Message result
 */
static LRESULT CALLBACK MonitorWindowProc(HWND hwnd, UINT uMsg, WPARAM wParam, LPARAM lParam) {
    switch (uMsg) {
        case WM_DISPLAYCHANGE: {
            // Check if monitor count changed (multi-monitor connect/disconnect)
            int oldMonitorCount = monitorCount;
            int newMonitorCount = 0;
            EnumDisplayMonitors(nullptr, nullptr, [](HMONITOR, HDC, LPRECT, LPARAM count) -> BOOL {
                (*(int*)count)++;
                return TRUE;
            }, (LPARAM)&newMonitorCount);

            if (oldMonitorCount != newMonitorCount) {
                // Monitor count changed - could notify Java if needed
            }

            if (!g_jvm || !g_displayObj) return 0;

            JNIEnv* env;
            jint attachResult = g_jvm->GetEnv((void**)&env, JNI_VERSION_1_6);
            bool didAttach = false;

            if (attachResult == JNI_EDETACHED) {
                if (g_jvm->AttachCurrentThread((void**)&env, nullptr) == 0) {
                    didAttach = true;
                } else {
                    return 0;
                }
            } else if (attachResult != JNI_OK) {
                return 0;
            }

            // Get actual resolution from EnumDisplaySettings (not GetSystemMetrics)
            int width = 0, height = 0;
            DEVMODE dm = {};
            dm.dmSize = sizeof(dm);
            int refreshRate = 60;
            int orientation = 0;
            if (EnumDisplaySettings(NULL, ENUM_CURRENT_SETTINGS, &dm)) {
                width = dm.dmPelsWidth;
                height = dm.dmPelsHeight;
                if (dm.dmFields & DM_DISPLAYFREQUENCY) refreshRate = dm.dmDisplayFrequency;
                if (dm.dmFields & DM_DISPLAYORIENTATION) {
                    switch (dm.dmDisplayOrientation) {
                        case DMDO_DEFAULT: orientation = 0; break;
                        case DMDO_90: orientation = 1; break;
                        case DMDO_180: orientation = 2; break;
                        case DMDO_270: orientation = 3; break;
                    }
                }
            } else {
                // Fallback to GetSystemMetrics
                width = GetSystemMetrics(SM_CXSCREEN);
                height = GetSystemMetrics(SM_CYSCREEN);
            }

            // Get DPI - always query current DPI from monitor
            int dpi = 96;
            HMONITOR hMonitor = MonitorFromWindow(hwnd ? hwnd : GetDesktopWindow(), MONITOR_DEFAULTTOPRIMARY);
            int monitorIndex = 0;
            if (hMonitor) {
                UINT dpiX = 96, dpiY = 96;
                if (SUCCEEDED(GetDpiForMonitor(hMonitor, MDT_EFFECTIVE_DPI, &dpiX, &dpiY))) {
                    dpi = (int)dpiX;
                }
                // Find monitor index
                monitorIndex = findMonitorIndex(hMonitor);
            }

            // Separate resolution and orientation events
            bool resolutionChanged = (width != lastWidth || height != lastHeight || dpi != lastDpi);
            bool orientationChanged = (orientation != lastOrientation);

            if (resolutionChanged && g_notifyMethodId) {
                env->CallVoidMethod(g_displayObj, g_notifyMethodId, monitorIndex, width, height, dpi, refreshRate);
                lastWidth = width;
                lastHeight = height;
                lastDpi = dpi;
            }

            if (orientationChanged && g_notifyOrientationChangedMethodId) {
                env->CallVoidMethod(g_displayObj, g_notifyOrientationChangedMethodId, monitorIndex, orientation);
                lastOrientation = orientation;
            }

            // DPI change detection fallback (in case WM_DPICHANGED doesn't arrive) - FastTheme approach
            if (g_notifyDPIMethodId && lastDpi != 0 && lastDpi != dpi) {
                int scalePercent = dpi * 100 / 96;
                env->CallVoidMethod(g_displayObj, g_notifyDPIMethodId, dpi, scalePercent);
            }

            if (didAttach) {
                g_jvm->DetachCurrentThread();
            }
            return 0;
        }

        case WM_SETTINGCHANGE: {
            // Check if this is a color profile change
            if (lParam) {
                LPCWSTR lParamStr = (LPCWSTR)lParam;
                if (wcsstr(lParamStr, L"ICM") != nullptr ||
                    wcsstr(lParamStr, L"ColorProfile") != nullptr ||
                    wcsstr(lParamStr, L"Color") != nullptr ||
                    wcsstr(lParamStr, L"Display") != nullptr) {
                    // Color profile change detected
                }
            }
            // Check if this is a DPI change by querying current DPI
            HMONITOR hMonitor = MonitorFromWindow(hwnd, MONITOR_DEFAULTTONEAREST);
            if (hMonitor) {
                UINT dpiX = 96, dpiY = 96;
                if (SUCCEEDED(GetDpiForMonitor(hMonitor, MDT_EFFECTIVE_DPI, &dpiX, &dpiY))) {
                    int scalePercent = (dpiX * 100) / 96;
                    // DPI changed - could notify Java if needed
                }
            }
            return 0;
        }

        case WM_DPICHANGED: {
            int newDpi = HIWORD(wParam);
            int scalePercent = (newDpi * 100) / 96;
            RECT* const prcNewWindow = (RECT*)lParam;
            if (prcNewWindow) {
                SetWindowPos(hwnd, NULL,
                    prcNewWindow->left, prcNewWindow->top,
                    prcNewWindow->right - prcNewWindow->left,
                    prcNewWindow->bottom - prcNewWindow->top,
                    SWP_NOZORDER | SWP_NOACTIVATE | SWP_SHOWWINDOW);
            }

            // Fire resolution event with new DPI (combining DPI with resolution)
            if (g_jvm && g_displayObj && g_notifyMethodId) {
                JNIEnv* env;
                jint attachResult = g_jvm->GetEnv((void**)&env, JNI_VERSION_1_6);
                bool didAttach = false;

                if (attachResult == JNI_EDETACHED) {
                    if (g_jvm->AttachCurrentThread((void**)&env, nullptr) == 0) {
                        didAttach = true;
                    } else {
                        return 0;
                    }
                } else if (attachResult != JNI_OK) {
                    return 0;
                }

                // Get monitor index for this DPI change
                HMONITOR hMonitor = MonitorFromWindow(hwnd, MONITOR_DEFAULTTONEAREST);
                int monitorIndex = 0;
                if (hMonitor) {
                    monitorIndex = findMonitorIndex(hMonitor);
                }

                // Re-enumerate monitors to get updated resolution (DPI changes often accompany resolution changes)
                {
                    std::lock_guard<std::mutex> lock(monitorMutex);
                    monitorCount = 0;
                    EnumDisplayMonitors(nullptr, nullptr, EnumMonitorsCallback, 0);
                    if (monitorIndex >= 0 && monitorIndex < monitorCount) {
                        int width = monitors[monitorIndex].width;
                        int height = monitors[monitorIndex].height;
                        int refreshRate = monitors[monitorIndex].refreshRate;
                        monitors[monitorIndex].dpi = newDpi;  // Ensure DPI is updated
                        // Fire resolution event with new DPI
                        env->CallVoidMethod(g_displayObj, g_notifyMethodId, monitorIndex, width, height, newDpi, refreshRate);
                    }
                }

                if (didAttach) {
                    g_jvm->DetachCurrentThread();
                }
            }
            return 0;
        }

        case WM_CLOSE:
            DestroyWindow(hwnd);
            return 0;

        case WM_DESTROY:
            PostQuitMessage(0);
            return 0;
    }
    return DefWindowProcA(hwnd, uMsg, wParam, lParam);
}

/**
 * @brief Background monitoring thread
 * 
 * Creates a hidden window to receive Windows display change messages.
 * Starts DPI polling timer for DPI detection.
 * Runs the message loop until the window is destroyed.
 * 
 * @param lpParam Thread parameter (unused)
 * @return Thread exit code (0 on success, 1 on failure)
 */
static DWORD WINAPI MonitorThread(LPVOID lpParam) {
    // Set DPI awareness BEFORE creating the window (FastTheme approach)
    SetThreadDpiAwarenessContext(DPI_AWARENESS_CONTEXT_PER_MONITOR_AWARE_V2);

    WNDCLASSA wc = {};
    wc.lpfnWndProc = MonitorWindowProc;
    wc.hInstance = GetModuleHandle(nullptr);
    wc.lpszClassName = "FastDisplayMonitor";

    if (!RegisterClassA(&wc)) {
        return 1;
    }

    // Use normal window without WS_VISIBLE (like backup version) to receive WM_DPICHANGED
    HWND hwnd = CreateWindowExA(
        0,
        "FastDisplayMonitor",
        "FastDisplay Monitor",
        WS_OVERLAPPEDWINDOW,
        0, 0, 0, 0,
        NULL, NULL, GetModuleHandleA(NULL), NULL
    );

    if (!hwnd) {
        return 1;
    }

    g_hwnd = hwnd;

    // Start DPI polling timer (every 500ms)
    g_dpiMonitoring.store(true);
    g_dpiTimer = SetTimer(hwnd, 2, 500, DPICallback);

    MSG msg = { 0 };
    while (GetMessage(&msg, nullptr, 0, 0)) {
        TranslateMessage(&msg);
        DispatchMessage(&msg);
    }

    // Cleanup DPI timer
    if (g_dpiTimer != 0) {
        KillTimer(hwnd, g_dpiTimer);
        g_dpiTimer = 0;
    }
    g_dpiMonitoring.store(false);

    return 0;
}

